		// FormatsIsNil applies the IsNil predicate on the "formats" field.
		func FormatsIsNil() predicate.MediaSource {
				return predicate.MediaSource(sql.FieldIsNull(FieldFormats))
		}
	
		
		
		
		
		// FormatsNotNil applies the NotNil predicate on the "formats" field.
		func FormatsNotNil() predicate.MediaSource {
				return predicate.MediaSource(sql.FieldNotNull(FieldFormats))
		}
	



	
	// HasItem applies the HasEdge predicate on the "item" edge.
	func HasItem() predicate.MediaSource {
		return predicate.MediaSource(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
				sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ItemTable,ItemColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
	}
	
	// HasItemWith applies the HasEdge predicate on the "item" edge with a given conditions (other predicates).
	func HasItemWith(preds ...predicate.Item) predicate.MediaSource {
		return predicate.MediaSource(func(s *sql.Selector) {
		step := newItemStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
	}

	
